-- Twins Sushi — carte Indigo VF2 corrigée = VF4 (24 novembre 2026, 146 produits) : Neige Crevette Pochée Avocat 45 (« crevette pochée, avocat, oignon crispy », Houssam 24 nov.) dans les Street Rolls, plus de California Crevette Pochée.
-- À exécuter APRÈS migration-carte-vf.sql, dans le SQL Editor de Supabase, après avoir vérifié la sauvegarde.
-- Remplace uniquement la carte (catégories + plats). Réglages, horaires, comptes admin : intacts.
-- L'ancienne carte est d'abord copiée dans « snapshots » (restaurable depuis Sécurité & sauvegardes dans l'admin).

begin;

select 'menu', jsonb_build_object('categories', coalesce((
  select jsonb_agg(jsonb_build_object('id', c.id, 'title', c.title, 'jp', c.jp, 'visible', c.visible, 'items', coalesce((
    select jsonb_agg(jsonb_build_object('code', i.code, 'name', i.name, 'desc', i.description, 'price', i.price, 'pcs', i.pcs,
      'showPcs', i.show_pcs, 'badge', i.badge, 'img', i.image, 'available', i.available, 'visible', i.visible) order by i.sort_order)
    from public.items i where i.category_id = c.id), '[]'::jsonb)) order by c.sort_order)
  from public.categories c), '[]'::jsonb));

delete from public.items;
delete from public.categories;



commit;
